-- ==========================================================================
-- Seed 20 cases for agenda-registry.html's "คิวรอบรรจุวาระ" (pending-agenda
-- queue) -- requested split evenly across the 3 category filter buckets
-- (getQueueCaseCategory() in agenda-registry.html): 7 NEW, 7 RETURN, 6 URGENT.
--
-- The queue reads live from tbl_res_request (status IN AGENDA_SET/013 =
-- DEFERRED/PENDING_INVITE_72), joined to tbl_cmp_case -- not the ECMIS.CASES
-- mock fallback, which only kicks in on a real Supabase error. So these are
-- real rows, not just JS mock data, matching how production data would look.
--
-- Category mapping (see getQueueCaseCategory() in agenda-registry.html):
--   NEW    = trr_status AGENDA_SET (011), trr_urgent = false
--   RETURN = trr_status DEFERRED  (013), trr_urgent = false
--   URGENT = trr_urgent = true (overrides NEW/RETURN regardless of status)
-- ==========================================================================

WITH new_cases AS (
  INSERT INTO public.tbl_cmp_case
    (tcc_no, tcc_subject, tcc_allegation, tcc_legal_base, tcc_complainant, tcc_owner, tcc_owner_org, tcc_received_date, tcc_doc_type)
  VALUES
    -- 7 NEW
    ('3001/2569', 'กล่าวหาเจ้าหน้าที่โรงพยาบาลชุมชนแห่งหนึ่ง ทุจริตจัดซื้อวัสดุการแพทย์ราคาสูงเกินจริง', 'จัดซื้อวัสดุการแพทย์ในราคาสูงกว่าท้องตลาดอย่างมีนัยสำคัญ โดยเอื้อประโยชน์ให้ผู้ขายรายเดียว', 'ม.18/4', 'ผู้ร้องขอไม่เปิดเผยชื่อ', 'นายประเสริฐ ตรวจสอบดี', 'กองปราบปรามการทุจริตในภาครัฐ 1', '2026-06-02', '213'),
    ('3002/2569', 'กล่าวหาเจ้าหน้าที่เทศบาลแห่งหนึ่ง เรียกรับผลประโยชน์เพื่อออกใบอนุญาตก่อสร้าง', 'เรียกรับเงินจากผู้ยื่นขออนุญาตก่อสร้างเป็นการตอบแทนการออกใบอนุญาตให้รวดเร็วกว่าปกติ', 'ม.18/4', 'ผู้ประกอบการรายหนึ่ง', 'นางสาวพิมพ์ใจ ซื่อสัตย์', 'สำนักงานคณะกรรมการป้องกันและปราบปรามการทุจริตในภาครัฐ เขต 3', '2026-06-10', '213'),
    ('3003/2569', 'กล่าวหาเจ้าหน้าที่ อบต. แห่งหนึ่ง ทุจริตโครงการก่อสร้างสะพานข้ามคลอง', 'ก่อสร้างสะพานไม่ตรงตามแบบและปริมาณงานจริง เบิกจ่ายเงินงบประมาณครบตามสัญญาทั้งที่งานไม่แล้วเสร็จ', 'ม.18/4', 'ประชาชนในพื้นที่', 'นายวิรัตน์ คงมั่น', 'กองปราบปรามการทุจริตในภาครัฐ 2', '2026-06-18', '213'),
    ('3004/2569', 'กล่าวหาเจ้าหน้าที่สำนักงานที่ดินจังหวัดแห่งหนึ่ง ออกโฉนดที่ดินโดยมิชอบ', 'ออกโฉนดที่ดินทับที่สาธารณประโยชน์โดยรู้อยู่แล้วว่าไม่ถูกต้องตามระเบียบ', 'ม.18/4', 'สำนักงานที่ดินจังหวัด', 'นางสาวอรอนงค์ พิทักษ์สิทธิ์', 'สำนักงานคณะกรรมการป้องกันและปราบปรามการทุจริตในภาครัฐ เขต 5', '2026-06-25', '213'),
    ('3005/2569', 'กล่าวหาเจ้าหน้าที่ อบต. แห่งหนึ่ง ทุจริตเบิกจ่ายเบี้ยยังชีพผู้สูงอายุ', 'จัดทำบัญชีรายชื่อผู้สูงอายุปลอมเพื่อเบิกจ่ายเงินเบี้ยยังชีพแล้วนำเงินมาใช้ส่วนตัว', 'ม.18/4', 'ผู้ร้องขอไม่เปิดเผยชื่อ', 'นายสมพงษ์ ยุติธรรม', 'กองปราบปรามการทุจริตในภาครัฐ 3', '2026-07-01', '213'),
    ('3006/2569', 'กล่าวหาเจ้าหน้าที่ตำรวจนายหนึ่ง เรียกรับเงินเพื่อช่วยเหลือคดี', 'เรียกรับเงินจากญาติผู้ต้องหาเพื่อแลกกับการดำเนินคดีที่เบาลง', 'ม.18/4', 'ญาติผู้ต้องหา', 'นายเอกชัย ไม่ประนีประนอม', 'สำนักงานคณะกรรมการป้องกันและปราบปรามการทุจริตในภาครัฐ เขต 1', '2026-07-08', '213'),
    ('3007/2569', 'กล่าวหาเจ้าหน้าที่โรงเรียนแห่งหนึ่ง ทุจริตจัดซื้อครุภัณฑ์คอมพิวเตอร์', 'จัดซื้อครุภัณฑ์คอมพิวเตอร์ไม่ตรงสเปคตามที่กำหนดในสัญญา แต่เบิกจ่ายเงินเต็มจำนวน', 'ม.18/4', 'ผู้ปกครองนักเรียน', 'นางสาวกาญจนา รักษาระเบียบ', 'กองปราบปรามการทุจริตในภาครัฐ 1', '2026-07-14', '213'),
    -- 7 RETURN (เลื่อน/ถอนวาระเดิม รอบรรจุวาระใหม่)
    ('3008/2569', 'กล่าวหาเจ้าหน้าที่เทศบาลตำบลแห่งหนึ่ง ทุจริตโครงการปรับปรุงถนนลาดยาง', 'ปรับปรุงถนนไม่ได้มาตรฐานตามแบบก่อสร้าง เบิกจ่ายเงินงบประมาณครบถ้วนทั้งที่งานบกพร่อง', 'ม.18/4', 'ประชาชนในพื้นที่', 'นายสมชาย ใจซื่อ', 'สำนักงานคณะกรรมการป้องกันและปราบปรามการทุจริตในภาครัฐ เขต 1', '2026-04-10', '213'),
    ('3009/2569', 'กล่าวหาเจ้าหน้าที่สรรพากรพื้นที่แห่งหนึ่ง เรียกรับผลประโยชน์คืนภาษี', 'เรียกรับเงินจากผู้ยื่นขอคืนภาษีเป็นการตอบแทนการเร่งรัดดำเนินการคืนภาษีให้เร็วขึ้น', 'ม.18/4', 'ผู้ประกอบการรายหนึ่ง', 'นายฉัตรชัย ตรวจการ', 'สำนักงานคณะกรรมการป้องกันและปราบปรามการทุจริตในภาครัฐ เขต 2', '2026-04-18', '213'),
    ('3010/2569', 'กล่าวหาเจ้าหน้าที่โรงพยาบาลส่งเสริมสุขภาพตำบลแห่งหนึ่ง ทุจริตจัดซื้อยาและเวชภัณฑ์', 'จัดซื้อยาและเวชภัณฑ์ผ่านตัวแทนจำหน่ายที่ไม่มีคุณสมบัติตามระเบียบพัสดุ', 'ม.18/4', 'บุคลากรภายในหน่วยงาน', 'นางสาวปรียา ตั้งมั่น', 'กองปราบปรามการทุจริตในภาครัฐ 2', '2026-04-25', '213'),
    ('3011/2569', 'กล่าวหาเจ้าหน้าที่สำนักงานที่ดินจังหวัดแห่งหนึ่ง เรียกรับเงินค่ารังวัดที่ดิน', 'เรียกรับเงินเกินกว่าอัตราค่าธรรมเนียมที่กฎหมายกำหนดในการรังวัดที่ดิน', 'ม.18/4', 'ประชาชนผู้ขอรังวัด', 'นายกิตติ แยกสำนวนดี', 'กองปราบปรามการทุจริตในภาครัฐ 3', '2026-05-02', '213'),
    ('3012/2569', 'กล่าวหาเจ้าหน้าที่ชลประทานแห่งหนึ่ง ทุจริตโครงการขุดลอกคลองชลประทาน', 'ขุดลอกคลองไม่ครบตามปริมาณดินที่กำหนดในสัญญา แต่ตรวจรับงานและเบิกจ่ายเงินครบถ้วน', 'ม.18/4', 'เกษตรกรในพื้นที่', 'นางสาวนภวรรณ ทบทวนคดี', 'สำนักงานคณะกรรมการป้องกันและปราบปรามการทุจริตในภาครัฐ เขต 4', '2026-05-09', '213'),
    ('3013/2569', 'กล่าวหาเจ้าหน้าที่ อบต. แห่งหนึ่ง เบิกจ่ายค่าล่วงเวลาเป็นเท็จ', 'จัดทำหลักฐานการปฏิบัติงานล่วงเวลาอันเป็นเท็จเพื่อเบิกจ่ายเงินค่าตอบแทนล่วงเวลา', 'ม.18/4', 'บุคลากรภายในหน่วยงาน', 'นายอำนวย เที่ยงธรรม', 'กองปราบปรามการทุจริตในภาครัฐ 1', '2026-05-16', '213'),
    ('3014/2569', 'กล่าวหาเจ้าหน้าที่เทศบาลเมืองแห่งหนึ่ง ทุจริตจัดซื้อรถบรรทุกขยะ', 'กำหนดสเปครถบรรทุกขยะเอื้อประโยชน์ให้ผู้เสนอราคารายใดรายหนึ่งโดยเฉพาะเจาะจง', 'ม.18/4', 'ผู้เสนอราคารายอื่น', 'นายวิชัย ยุติธรรม', 'สำนักงานคณะกรรมการป้องกันและปราบปรามการทุจริตในภาครัฐ เขต 6', '2026-05-23', '213'),
    -- 6 URGENT
    ('3015/2569', 'กล่าวหาเจ้าหน้าที่ปศุสัตว์จังหวัดแห่งหนึ่ง ทุจริตจัดซื้อวัคซีนป้องกันโรคระบาดสัตว์', 'จัดซื้อวัคซีนไม่ตรงตามคุณลักษณะเฉพาะ ใกล้หมดอายุ และมีปริมาณไม่ครบตามสัญญา ระหว่างสถานการณ์โรคระบาดเร่งด่วน', 'ม.18/4', 'กรมปศุสัตว์', 'นายประเสริฐ ตรวจสอบดี', 'กองปราบปรามการทุจริตในภาครัฐ 1', '2026-08-10', '213'),
    ('3016/2569', 'กล่าวหาเจ้าหน้าที่ที่ว่าการอำเภอแห่งหนึ่ง เรียกรับเงินเพื่อออกบัตรประจำตัวประชาชน', 'เรียกรับเงินจากประชาชนเพื่อแลกกับการออกบัตรประชาชนเร่งด่วนนอกคิวปกติ ใกล้ครบกำหนดรายงานผล', 'ม.18/4', 'ประชาชนผู้ร้องเรียน', 'นางสาวพิมพ์ใจ ซื่อสัตย์', 'สำนักงานคณะกรรมการป้องกันและปราบปรามการทุจริตในภาครัฐ เขต 3', '2026-08-12', '213'),
    ('3017/2569', 'กล่าวหาเจ้าหน้าที่ท้องถิ่นแห่งหนึ่ง ทุจริตงบกลางช่วยเหลือผู้ประสบอุทกภัย', 'จัดทำบัญชีรายชื่อผู้ประสบอุทกภัยเกินจริงเพื่อเบิกจ่ายเงินช่วยเหลือ ต้องเร่งรัดก่อนปิดรอบงบประมาณ', 'ม.18/4', 'ผู้ประสบภัยจริงในพื้นที่', 'นายวิรัตน์ คงมั่น', 'กองปราบปรามการทุจริตในภาครัฐ 2', '2026-08-14', '213'),
    ('3018/2569', 'กล่าวหาเจ้าหน้าที่ศุลกากรด่านแห่งหนึ่ง เรียกรับสินบนเพื่อปล่อยสินค้า', 'เรียกรับเงินจากผู้นำเข้าสินค้าเพื่อแลกกับการเร่งรัดตรวจปล่อยสินค้าโดยไม่ตรวจสอบตามระเบียบ', 'ม.18/4', 'ผู้นำเข้าสินค้ารายหนึ่ง', 'นายเอกชัย ไม่ประนีประนอม', 'สำนักงานคณะกรรมการป้องกันและปราบปรามการทุจริตในภาครัฐ เขต 1', '2026-08-16', '213'),
    ('3019/2569', 'กล่าวหาเจ้าหน้าที่เกษตรจังหวัดแห่งหนึ่ง ทุจริตโครงการเยียวยาเกษตรกรผู้ประสบภัยแล้ง', 'จัดทำบัญชีเกษตรกรปลอมเพื่อเบิกจ่ายเงินเยียวยา อยู่ระหว่างกรอบเวลาเร่งด่วนก่อนสิ้นสุดมาตรการ', 'ม.18/4', 'เกษตรกรจริงในพื้นที่', 'นางสาวอรอนงค์ พิทักษ์สิทธิ์', 'สำนักงานคณะกรรมการป้องกันและปราบปรามการทุจริตในภาครัฐ เขต 5', '2026-08-18', '213'),
    ('3020/2569', 'กล่าวหาเจ้าหน้าที่สถาบันพัฒนาฝีมือแรงงานแห่งหนึ่ง ทุจริตงบประมาณจัดฝึกอบรม', 'จัดทำหลักฐานผู้เข้ารับการฝึกอบรมเป็นเท็จเพื่อเบิกจ่ายงบประมาณ ต้องรายงานผลก่อนสิ้นปีงบประมาณ', 'ม.18/4', 'ผู้ร้องขอไม่เปิดเผยชื่อ', 'นายสมพงษ์ ยุติธรรม', 'กองปราบปรามการทุจริตในภาครัฐ 3', '2026-08-20', '213')
  RETURNING tcc_id, tcc_no
)
INSERT INTO public.tbl_res_request (tcc_id, trr_status, trr_urgent, trr_sla_days, trr_sla_limit)
SELECT
  tcc_id,
  CASE
    WHEN tcc_no IN ('3008/2569','3009/2569','3010/2569','3011/2569','3012/2569','3013/2569','3014/2569')
      THEN '013' -- DEFERRED -> RETURN bucket
    ELSE '011'    -- AGENDA_SET -> NEW/URGENT bucket
  END,
  tcc_no IN ('3015/2569','3016/2569','3017/2569','3018/2569','3019/2569','3020/2569'), -- trr_urgent -> URGENT bucket (overrides above)
  0, 5
FROM new_cases;
